<?php $__env->startSection('content'); ?><div class="mb-4"><a href="<?php echo e(route('mahasiswa.index')); ?>" class="text-decoration-none">&larr; Kembali</a><h1 class="h3 fw-bold mt-3"><?php echo e($mahasiswa->exists ? 'Edit Mahasiswa' : 'Tambah Mahasiswa'); ?></h1></div><div class="card form-card"><div class="card-body p-4"><form method="POST" action="<?php echo e($mahasiswa->exists ? route('mahasiswa.update',$mahasiswa) : route('mahasiswa.store')); ?>"><?php echo csrf_field(); ?> <?php if($mahasiswa->exists): ?> <?php echo method_field('PUT'); ?> <?php endif; ?><div class="row g-3"><div class="col-md-4"><label class="form-label">NIM</label><input name="nim" value="<?php echo e(old('nim',$mahasiswa->nim)); ?>" class="form-control" required></div><div class="col-md-8"><label class="form-label">Nama lengkap</label><input name="nama" value="<?php echo e(old('nama',$mahasiswa->nama)); ?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" type="email" value="<?php echo e(old('email',$mahasiswa->email)); ?>" class="form-control"></div><div class="col-md-3"><label class="form-label">Jenis kelamin</label><select name="jenis_kelamin" class="form-select" required><option value="">Pilih</option><option value="L" <?php if(old('jenis_kelamin',$mahasiswa->jenis_kelamin)==='L'): echo 'selected'; endif; ?>>Laki-laki</option><option value="P" <?php if(old('jenis_kelamin',$mahasiswa->jenis_kelamin)==='P'): echo 'selected'; endif; ?>>Perempuan</option></select></div><div class="col-md-3"><label class="form-label">Tanggal lahir</label><input name="tanggal_lahir" type="date" value="<?php echo e(old('tanggal_lahir',$mahasiswa->tanggal_lahir?->format('Y-m-d'))); ?>" class="form-control"></div><div class="col-md-6"><label class="form-label">Jurusan</label><select name="jurusan_id" class="form-select" required><option value="">Pilih jurusan</option><?php $__currentLoopData = $jurusans; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $jurusan): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($jurusan->id); ?>" <?php if(old('jurusan_id',$mahasiswa->jurusan_id)==$jurusan->id): echo 'selected'; endif; ?>><?php echo e($jurusan->kode); ?> - <?php echo e($jurusan->nama); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Kelas</label><select name="kelas_id" class="form-select" required><option value="">Pilih kelas</option><?php $__currentLoopData = $kelases; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $kelas): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($kelas->id); ?>" <?php if(old('kelas_id',$mahasiswa->kelas_id)==$kelas->id): echo 'selected'; endif; ?>><?php echo e($kelas->nama); ?> (<?php echo e($kelas->tahun_ajaran); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-12"><label class="form-label">Alamat</label><textarea name="alamat" class="form-control" rows="3"><?php echo e(old('alamat',$mahasiswa->alamat)); ?></textarea></div></div><button class="btn btn-primary mt-4">Simpan data</button></form></div></div><?php $__env->stopSection(); ?>

